inline bool VerifyOpArgs(::flatbuffers::Verifier &verifier, const void *obj, OpArgs type) {
  switch (type) {
    case OpArgs::NONE: {
      return true;
    }
    case OpArgs::KofNArgs: {
      auto ptr = reinterpret_cast<const pcfb::KofNArgs *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case OpArgs::MonteCarloExpectedValueOptions: {
      auto ptr = reinterpret_cast<const pcfb::MonteCarloExpectedValueOptions *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyOpArgsVector(::flatbuffers::Verifier &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<OpArgs> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyOpArgs(
        verifier,  values->Get(i), types->GetEnum<OpArgs>(i))) {
      return false;
    }
  }
  return true;
}

inline void *OpArgsUnion::UnPack(const void *obj, OpArgs type, const ::flatbuffers::resolver_function_t *resolver) {
  (void)resolver;
  switch (type) {
    case OpArgs::KofNArgs: {
      auto ptr = reinterpret_cast<const pcfb::KofNArgs *>(obj);
      return ptr->UnPack(resolver);
    }
    case OpArgs::MonteCarloExpectedValueOptions: {
      auto ptr = reinterpret_cast<const pcfb::MonteCarloExpectedValueOptions *>(obj);
      return ptr->UnPack(resolver);
    }
    default: return nullptr;
  }
}

inline ::flatbuffers::Offset<void> OpArgsUnion::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const ::flatbuffers::rehasher_function_t *_rehasher) const {
  (void)_rehasher;
  switch (type) {
    case OpArgs::KofNArgs: {
      auto ptr = reinterpret_cast<const pcfb::KofNArgsT *>(value);
      return CreateKofNArgs(_fbb, ptr, _rehasher).Union();
    }
    case OpArgs::MonteCarloExpectedValueOptions: {
      auto ptr = reinterpret_cast<const pcfb::MonteCarloExpectedValueOptionsT *>(value);
      return CreateMonteCarloExpectedValueOptions(_fbb, ptr, _rehasher).Union();
    }
    default: return 0;
  }
}

inline OpArgsUnion::OpArgsUnion(const OpArgsUnion &u) : type(u.type), value(nullptr) {
  switch (type) {
    case OpArgs::KofNArgs: {
      value = new pcfb::KofNArgsT(*reinterpret_cast<pcfb::KofNArgsT *>(u.value));
      break;
    }
    case OpArgs::MonteCarloExpectedValueOptions: {
      value = new pcfb::MonteCarloExpectedValueOptionsT(*reinterpret_cast<pcfb::MonteCarloExpectedValueOptionsT *>(u.value));
      break;
    }
    default:
      break;
  }
}

inline void OpArgsUnion::Reset() {
  switch (type) {
    case OpArgs::KofNArgs: {
      auto ptr = reinterpret_cast<pcfb::KofNArgsT *>(value);
      delete ptr;
      break;
    }
    case OpArgs::MonteCarloExpectedValueOptions: {
      auto ptr = reinterpret_cast<pcfb::MonteCarloExpectedValueOptionsT *>(value);
      delete ptr;
      break;
    }
    default: break;
  }
  value = nullptr;
  type = OpArgs::NONE;
}

